const base64Data = $json.resume_file_base64;
const binaryBuffer = Buffer.from(base64Data, 'base64');

return {
  json: {
    candidate_id: $json.candidate_id,
    role: $json.role,
    job_description: $json.job_description
  },
  binary: {
    Your_File: {
      data: binaryBuffer.toString('base64'),
      mimeType: 'application/pdf',
      fileName: 'resume.pdf'
    }
  }
};

let results = items.map(item => item.json);

// Sort by highest score
results.sort((a, b) => b.role_fit_score - a.role_fit_score);

return [{
  json: {
    role: $node["Webhook"].json.body.role,
    job_description: $node["Webhook"].json.body.job_description,
    results: results
  }
}];
